const topics = [];

function add(pillar, subCluster, persona, assetClass, slug, title, summary, isFlagship = false) {
  const pObj = PILLARS.find(p => p.id === pillar);
  topics.push({
    id: `topic-${topics.length + 1}`,
    title,
    pillar,
    pillarName: pObj ? pObj.name : 'Knowledge Hub',
    subCluster,
    persona,
    assetClass,
    slug,
    summary,
    isFlagship,
  });
}

